pub fn prime_num(n: u64) -> bool {
    // By definition in this problem, n is assumed to be at least 2,
    // but we'll still handle smaller inputs gracefully.
    if n < 2 {
        return false;
    }
    // 2 is prime
    if n == 2 {
        return true;
    }
    // even numbers > 2 are not prime
    if n % 2 == 0 {
        return false;
    }
    // trial division by odd numbers up to sqrt(n)
    let mut k: u64 = 3;
    while k * k <= n {
        if n % k == 0 {
            return false;
        }
        k += 2;
    }
    true
}

